<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Refresh, Plus } from '@element-plus/icons-vue'
import { getFundAccounts, getSettlements, createSettlement, approveSettlement, completeSettlement, rejectSettlement } from '../../../api/admin/finance'

const loading = ref(false); const error = ref(''); const accounts = ref<any[]>([]); const settlements = ref<any[]>([])
const status = ref<number>(); const merchantId = ref<number>(); const dialog = ref(false); const saving = ref(false)
const form = ref({ merchantId: undefined as number | undefined, amount: undefined as number | undefined, payoutMethod: '平台人工结算', payoutAccountMask: '' })
const statusText: Record<number, string> = { 10: '待审核', 20: '已审核', 30: '已结算', 40: '已驳回' }
const money = (value: unknown) => `¥${Number(value || 0).toFixed(2)}`
const load = async () => { loading.value = true; error.value = ''; try { const [a, s] = await Promise.all([getFundAccounts(), getSettlements({ merchantId: merchantId.value, status: status.value })]); if (a.code !== 200 || s.code !== 200) throw new Error(); accounts.value = a.data || []; settlements.value = s.data || [] } catch { error.value = '资金数据加载失败，请稍后重试'; ElMessage.error(error.value) } finally { loading.value = false } }
const openCreate = (account?: any) => { form.value = { merchantId: account?.merchantId, amount: undefined, payoutMethod: '平台人工结算', payoutAccountMask: '' }; dialog.value = true }
const submitCreate = async () => { if (!form.value.merchantId || !form.value.amount || form.value.amount <= 0) return ElMessage.warning('请选择商家并填写有效金额'); saving.value = true; try { const r = await createSettlement({ merchantId: form.value.merchantId, amount: form.value.amount, payoutMethod: form.value.payoutMethod, payoutAccountMask: form.value.payoutAccountMask }); if (r.code !== 200) throw new Error(r.message); ElMessage.success('结算单已创建'); dialog.value = false; await load() } catch (e: any) { ElMessage.error(e.message || '创建结算单失败') } finally { saving.value = false } }
const act = async (kind: 'approve' | 'complete' | 'reject', row: any) => { try { const label = kind === 'approve' ? '审核' : kind === 'complete' ? '完成' : '驳回'; await ElMessageBox.confirm(`确认${label}结算单 ${row.settlementNo}？`, '操作确认', { type: kind === 'reject' ? 'warning' : 'info' }); const fn = kind === 'approve' ? approveSettlement : kind === 'complete' ? completeSettlement : rejectSettlement; const r = await fn(row.id, `${label}结算单`); if (r.code !== 200) throw new Error(r.message); ElMessage.success(`已${label}`); await load() } catch (e: any) { if (e !== 'cancel') ElMessage.error(e.message || '操作失败') } }
onMounted(load)
</script>

<template><div class="page-container" v-loading="loading"><div class="finance-page"><div class="page-head"><div><h2>商家结算</h2><p>管理商家可结算余额和平台内部结算单</p></div><div class="actions"><el-button :icon="Refresh" :loading="loading" @click="load">刷新</el-button><el-button type="primary" :icon="Plus" @click="openCreate()">创建结算</el-button></div></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false"/><section class="panel"><div class="section-head"><h3>商家资金账户</h3><span>{{ accounts.length }} 个账户</span></div><el-table :data="accounts" empty-text="暂无资金账户"><el-table-column prop="merchantId" label="商家 ID" width="170"/><el-table-column prop="availableBalance" label="可结算余额"><template #default="{row}">{{ money(row.availableBalance) }}</template></el-table-column><el-table-column prop="pendingBalance" label="待结算"><template #default="{row}">{{ money(row.pendingBalance) }}</template></el-table-column><el-table-column prop="frozenBalance" label="冻结余额"><template #default="{row}">{{ money(row.frozenBalance) }}</template></el-table-column><el-table-column label="操作" width="130" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openCreate(row)">创建结算</el-button></template></el-table-column></el-table></section><section class="panel"><div class="section-head"><h3>结算单</h3><div class="filters"><el-input-number v-model="merchantId" :controls="false" placeholder="商家 ID" size="small"/><el-select v-model="status" clearable placeholder="状态" size="small"><el-option v-for="(label,key) in statusText" :key="key" :label="label" :value="Number(key)"/></el-select><el-button size="small" @click="load">筛选</el-button></div></div><el-table :data="settlements" empty-text="暂无结算单"><el-table-column prop="settlementNo" label="结算单号" min-width="190" show-overflow-tooltip/><el-table-column prop="merchantId" label="商家 ID" width="150"/><el-table-column prop="netAmount" label="结算金额" width="125"><template #default="{row}">{{ money(row.netAmount) }}</template></el-table-column><el-table-column prop="settlementStatus" label="状态" width="100"><template #default="{row}">{{ statusText[row.settlementStatus] || '-' }}</template></el-table-column><el-table-column prop="createTime" label="创建时间" min-width="170"/><el-table-column label="操作" width="230" fixed="right"><template #default="{row}"><el-button v-if="row.settlementStatus===10" link type="primary" @click="act('approve',row)">审核</el-button><el-button v-if="row.settlementStatus===20" link type="success" @click="act('complete',row)">完成结算</el-button><el-button v-if="row.settlementStatus===10 || row.settlementStatus===20" link type="danger" @click="act('reject',row)">驳回</el-button></template></el-table-column></el-table></section></div><el-dialog v-model="dialog" title="创建结算单" width="460px"><el-form label-width="100px"><el-form-item label="商家 ID"><el-input-number v-model="form.merchantId" :controls="false"/></el-form-item><el-form-item label="结算金额"><el-input-number v-model="form.amount" :min="0.01" :precision="2"/></el-form-item><el-form-item label="结算方式"><el-input v-model="form.payoutMethod"/></el-form-item><el-form-item label="收款账户"><el-input v-model="form.payoutAccountMask" placeholder="仅填写脱敏信息"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitCreate">创建</el-button></template></el-dialog></div></template>

<style scoped>.finance-page{display:flex;flex-direction:column;gap:16px}.page-head{display:flex;justify-content:space-between;align-items:center}.page-head h2{margin:0;color:var(--bs-text-title);font-size:20px}.page-head p{margin:5px 0 0;color:var(--bs-text-muted);font-size:13px}.actions,.filters{display:flex;gap:8px;align-items:center}.panel{background:#fff;border:1px solid var(--bs-border-light);border-radius:8px;box-shadow:var(--bs-card-shadow);padding:18px}.section-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.section-head h3{margin:0;color:var(--bs-text-title);font-size:16px}.section-head span{color:var(--bs-text-muted);font-size:12px}.filters .el-input-number{width:120px}.filters .el-select{width:120px}@media(max-width:720px){.page-head,.section-head{align-items:flex-start;flex-direction:column;gap:12px}.actions,.filters{flex-wrap:wrap}}</style>
